require_once __DIR__ . '/../config/db.php'; require_once __DIR__ . '/../services/userService.php'; require_once __DIR__ . '/../includes/auth.php'; $pdo=openDatabase(); $user=requireLogin($pdo); requireRole($user,array('Administrator'));
$search=trim((string)(isset($_GET['search'])?$_GET['search']:''));$role=(string)(isset($_GET['role'])?$_GET['role']:'');$status=(string)(isset($_GET['status'])?$_GET['status']:'');if($role!==''&&!in_array($role,userRoles(),true)){$role='';}if($status!==''&&!in_array($status,userStatuses(),true)){$status='';}$rows=listUsers($pdo,$search,$role,$status);
require __DIR__ . '/../includes/header.php';require __DIR__ . '/../includes/nav.php';?><main class="container py-4"><h1>Manage users</h1><form method="get" class="row g-2 mb-3"><div class="col-md-4"><input class="form-control" name="search" placeholder="Name or email" value="<?=htmlspecialchars($search,ENT_QUOTES,'UTF-8')?>"></div><div class="col-md-3"><select class="form-select" name="role"><option value="">All roles</option><?php foreach(userRoles() as $v):?><option <?=$role===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select></div><div class="col-md-3"><select class="form-select" name="status"><option value="">All statuses</option><?php foreach(userStatuses() as $v):?><option <?=$status===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select></div><div class="col-auto"><button class="btn btn-primary">Search</button></div></form><?php if(!$rows):?><p>No matching accounts.</p><?php else:?><table class="table"><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><?=htmlspecialchars($row['full_name'],ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($row['email'],ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($row['role'],ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($row['status'],ENT_QUOTES,'UTF-8')?></td><td><a href="user-details.php?user_id=<?=(int)$row['user_id']?>">Manage</a></td></tr><?php endforeach;?></tbody></table><?php endif;?></main><?php require __DIR__ . '/../includes/footer.php'; ?>
